const base=document.body.dataset.base||'';
const toast=document.querySelector('.toast');let toastTimer;
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400);}
function applyTheme(theme){document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#101418':'#f4f6f7');document.querySelector('#theme').setAttribute('aria-label',theme==='dark'?'Switch to light theme':'Switch to dark theme');}
try{applyTheme(localStorage.getItem('nc-theme')||'dark');}catch{}
document.querySelector('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(theme);try{localStorage.setItem('nc-theme',theme);}catch{}};
document.querySelector('#menu').onclick=()=>{const button=document.querySelector('#menu');const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation':'Open navigation');button.textContent=open?'×':'☰';document.querySelector('#nav').classList.toggle('open',open);};
async function copy(text){try{await navigator.clipboard.writeText(text);notify('Code copied');}catch{notify('Copy failed. Select the code and copy it manually.');}}
function saveParameter(key,value){const url=new URL(location.href);if(value)url.searchParams.set(key,value);else url.searchParams.delete(key);history.replaceState(null,'',url);}
const surfaceTabs=[...document.querySelectorAll('[data-surface]')];
function selectSurface(button,persist=true){surfaceTabs.forEach(tab=>{const active=tab===button;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;document.getElementById(tab.getAttribute('aria-controls')).hidden=!active;});if(persist)saveParameter('surface',button.dataset.surface==='source'?'':button.dataset.surface);}
surfaceTabs.forEach(button=>button.addEventListener('click',()=>selectSurface(button)));
function restoreSurface(){const requested=new URLSearchParams(location.search).get('surface');const selected=surfaceTabs.find(tab=>tab.dataset.surface===requested)||surfaceTabs[0];if(selected)selectSurface(selected,false);}
restoreSurface();addEventListener('popstate',restoreSurface);
document.querySelector('#copy-active-surface')?.addEventListener('click',()=>copy(document.querySelector('.surface-panel:not([hidden]) pre code').textContent));
document.querySelectorAll('.copy').forEach(b=>b.onclick=()=>copy(b.closest('.code').querySelector('pre').textContent));
document.querySelector('.copy-hero')?.addEventListener('click',async()=>{try{const r=await fetch(base+'examples.json');if(!r.ok)throw Error();await copy((await r.json()).hello);}catch{notify('Could not load the example');}});
const normal=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const filter=document.querySelector('#library-filter');
function filterChapters(persist=true){const q=normal(filter.value.trim());let count=0;document.querySelectorAll('.chapter').forEach(a=>{const visible=a.dataset.search.includes(q);a.hidden=!visible;if(visible)count++;});document.querySelectorAll('.book-section').forEach(s=>s.hidden=!s.querySelector('.chapter:not([hidden])'));document.querySelector('#filter-count').textContent=`${count} ${count===1?'chapter':'chapters'}`;document.querySelector('#filter-empty').hidden=count!==0;if(persist)saveParameter('chapter',filter.value.trim());}
filter?.addEventListener('input',()=>filterChapters());
if(filter){filter.value=new URLSearchParams(location.search).get('chapter')||'';filterChapters(false);addEventListener('popstate',()=>{filter.value=new URLSearchParams(location.search).get('chapter')||'';filterChapters(false);});}
const dialog=document.querySelector('#search-dialog'),input=document.querySelector('#search-input'),results=document.querySelector('#search-results'),count=document.querySelector('#search-count');let index;
async function search(){results.replaceChildren();try{if(!index){const r=await fetch(base+'search.json');if(!r.ok)throw Error();index=await r.json();}const q=normal(input.value.trim());const found=index.filter(a=>normal(a.title+' '+a.text).includes(q));count.textContent=q?`${found.length} results`:'Browse chapters or enter a search term';for(const a of found.slice(0,30)){const li=document.createElement('li'),link=document.createElement('a'),title=document.createElement('strong'),group=document.createElement('span');link.href=base+a.url;title.textContent=a.title;group.textContent=a.group;link.append(title,group);li.append(link);results.append(li);}if(!found.length){const li=document.createElement('li');li.textContent='No matching term found. Try another word.';results.append(li);}}catch{count.textContent='Search could not be loaded. Browse the library instead.';}}
function openSearch(){dialog.showModal();input.focus();search();}
document.querySelectorAll('.search-open').forEach(b=>b.onclick=openSearch);document.querySelector('#search-close').onclick=()=>dialog.close();input.oninput=search;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog.open){e.preventDefault();dialog.close();return;}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();openSearch();}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});

const phases=[
 ['SOURCE','.n','Declare the program.','Functions, typed places and imports define program units. Visibility, control flow and representation must retain their identity through analysis.','examples/00_hello/hello.n','the-first-program'],
 ['ANALYSIS','AST','Resolve symbols and validate types.','The parser builds the AST. Semantic analysis resolves references and checks arity, types and control-flow restrictions before lowering.','parser → AST → semantics','parser-ast-semantics-and-ir'],
 ['REPRESENTATION','IR','Preserve semantics through lowering.','The IR retains information needed by later phases. Transformations must preserve source semantics and evaluation order.','compiler emit-ir hello.n','parser-ast-semantics-and-ir'],
 ['MATERIALIZATION','ABI','Resolve layout, ABI and relocations.','The target determines sizes, alignment, calling conventions and object format. MCT, backend and linking translate these contracts into bytes, symbols and relocations.','MCT → object → linking','materialization-abi-and-linking'],
 ['EXECUTION','01','Verify the image and its dependencies.','The executable and its providers must produce the expected output and effects. Kit smoke tests cover hello and arithmetic on Windows and Linux/WSL x86-64.','Hello, nC public beta · exit 0','what-bootstrap-v81-demonstrates']
];
function selectPhase(button,persist=true){const i=Number(button.dataset.phase),p=phases[i];document.querySelectorAll('[data-phase]').forEach(b=>{const active=b===button;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;b.classList.toggle('active',active);});document.querySelector('#phase-panel').setAttribute('aria-labelledby',button.id);document.querySelector('#phase-label').textContent=`0${i+1} / ${p[0]}`;document.querySelector('#phase-mark').textContent=p[1];document.querySelector('#phase-title').textContent=p[2];document.querySelector('#phase-description').textContent=p[3];document.querySelector('#phase-code').textContent=p[4];document.querySelector('#phase-link').href='library/'+p[5];if(persist)saveParameter('phase',i===0?'':String(i));}
document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>selectPhase(b));
function restorePhase(){const requested=new URLSearchParams(location.search).get('phase');const tab=document.querySelector('[data-phase="'+(/^[0-4]$/.test(requested)?requested:'0')+'"]');if(tab)selectPhase(tab,false);}
restorePhase();addEventListener('popstate',restorePhase);
const commands={windows:'.\\ncc.exe self-test\n.\\ncc.exe compiler emit-executable hello.n `\n  --target x86_64-pc-windows-msvc --out hello.exe\n.\\hello.exe',linux:'chmod +x ncc\n./ncc self-test\n./ncc compiler emit-executable hello.n \\\n  --target x86_64-unknown-linux-gnu --out hello\nchmod +x hello\nLD_LIBRARY_PATH="$PWD${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}" ./hello'};let selectedOS='windows';
function selectOS(button,persist=true){selectedOS=button.dataset.os;document.querySelectorAll('[data-os]').forEach(b=>{const active=b===button;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});document.querySelector('#terminal-panel').setAttribute('aria-labelledby',button.id);document.querySelector('#terminal-shell').textContent=selectedOS==='windows'?'PowerShell · inside the extracted kit':'Bash · inside the extracted kit';document.querySelector('#terminal-commands code').textContent=commands[selectedOS];if(persist)saveParameter('os',selectedOS==='windows'?'':selectedOS);}
document.querySelectorAll('[data-os]').forEach(b=>b.onclick=()=>selectOS(b));
function restoreOS(){const requested=new URLSearchParams(location.search).get('os');const tab=document.querySelector('[data-os="'+(requested==='linux'?'linux':'windows')+'"]');if(tab)selectOS(tab,false);}
restoreOS();addEventListener('popstate',restoreOS);
document.querySelector('#copy-commands')?.addEventListener('click',()=>copy(commands[selectedOS]));
document.querySelectorAll('[role="tablist"]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key))return;const tabs=[...list.querySelectorAll('[role="tab"]')],i=tabs.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:tabs.length-1))%tabs.length;tabs[next].focus();tabs[next].click();}));
const article=document.querySelector('[data-article-title]');if(article){try{localStorage.setItem('nc-reading',JSON.stringify({title:article.dataset.articleTitle,url:article.dataset.articleUrl}));}catch{}const progress=()=>{const available=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress span').style.width=(available>0?Math.min(100,Math.max(0,scrollY/available*100)):100)+'%';};window.addEventListener('scroll',progress,{passive:true});progress();}
const resume=document.querySelector('#continue-reading');if(resume){try{const previous=JSON.parse(localStorage.getItem('nc-reading'));if(previous&&/^library\/[a-z0-9-]+(?:\.html)?$/.test(previous.url)){resume.href=previous.url.replace(/\.html$/,'');resume.querySelector('strong').textContent=previous.title;resume.hidden=false;}}catch{}}

const mainMenu=document.querySelector('#menu');
function closeMenu(){mainMenu.setAttribute('aria-expanded','false');mainMenu.setAttribute('aria-label','Open navigation');mainMenu.textContent='☰';document.querySelector('#nav').classList.remove('open');}
document.querySelector('#nav').addEventListener('click',event=>{if(event.target.closest('a'))closeMenu();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mainMenu.getAttribute('aria-expanded')==='true'){closeMenu();mainMenu.focus();}});
